from collections import deque

def distance(start, target, edges):
    q = deque([(start, 0)])
    seen = {start}
    while q:
        node, d = q.popleft()
        if node == target:
            return d              # 처음 닿은 순간이 최소 단계 수다
        for nxt in edges.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, d + 1))
    return None

