def has_cycle(parents):
    state = {}                       # 0=방문중, 1=완료
    def visit(node):
        if state.get(node) == 0:     # 방문 중인 노드를 다시 만났다
            return True
        if state.get(node) == 1:
            return False
        state[node] = 0
        found = any(visit(p) for p in parents.get(node, []))
        state[node] = 1
        return found
    return any(visit(n) for n in parents)

