def usage(store):
    keys = sum(sys.getsizeof(k) for k in store.data)
    values = sum(sys.getsizeof(v) for v in store.data.values())
    table = sys.getsizeof(store.buckets)
    return {'keys': keys, 'values': values, 'table': table,
            'total': keys + values + table}

